a3=A.c(["\u0631\u06cc\u0641\u0627\u0645\u067e\u06cc\u0646","\u06a9\u0627\u0631\u0628\u0627\u0645\u0627\u0632\u067e\u06cc\u0646","\u0641\u0646\u06cc\u200c\u062a\u0648\u0626\u06cc\u0646","\u0641\u0646\u0648\u0628\u0627\u0631\u0628\u06cc\u062a\u0627\u0644","\u062a\u0648\u067e\u06cc\u0631\u0627\u0645\u0627\u062a","\u0627\u06a9\u0633\u200c\u06a9\u0627\u0631\u0628\u0627\u0632\u067e\u06cc\u0646","\u067e\u0631\u06cc\u0645\u06cc\u062f\u0648\u0646","\u0622\u0645\u0648\u06a9\u0633\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646","\u06a9\u0648\u0622\u0645\u0648\u06a9\u0633\u06cc\u200c\u06a9\u0644\u0627\u0648","\u0622\u0645\u067e\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646","\u062a\u062a\u0631\u0627\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646","\u062f\u0627\u06a9\u0633\u06cc\u200c\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646","\u06af\u0631\u06cc\u0632\u0626\u0648\u0641\u0648\u0644\u0648\u06cc\u0646"],s)
