if(b0.f_(b1,b2,o,n))return new A.cY(B.bt,"\u062a\u062f\u0627\u062e\u0644 \u0641\u0648\u0642\u200c\u0627\u0644\u0639\u0627\u062f\u0647 \u062e\u0637\u0631\u0646\u0627\u06a9 (\u0627\u0641\u062a \u06a9\u0634\u0646\u062f\u0647 \u0641\u0634\u0627\u0631 \u062e\u0648\u0646)","\u0645\u0635\u0631\u0641 \u0647\u0645\u0632\u0645\u0627\u0646 \xab"+b1.b+"\xbb \u0648 \xab"+b2.b+"\xbb \u06cc\u06a9\u06cc \u0627\u0632 \u062e\u0637\u0631\u0646\u0627\u06a9\u200c\u062a\u0631\u06cc\u0646 \u062a\u062f\u0627\u062e\u0644\u0627\u062a \u067e\u0632\u0634\u06a9\u06cc \u0627\u0633\u062a \u06a9\u0647 \u0628\u0627\u0639\u062b \u06af\u0634\u0627\u062f \u0634\u062f\u0646 \u0646\u0627\u06af\u0647\u0627\u0646\u06cc \u062a\u0645\u0627\u0645 \u0639\u0631\u0648\u0642 \u0648 \u0633\u0642\u0648\u0637 \u0634\u062f\u06cc\u062f \u0641\u0634\u0627\u0631 \u062e\u0648\u0646\u060c \u063a\u0634 \u0648 \u0627\u06cc\u0633\u062a \u0642\u0644\u0628\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f.","\u062a\u0634\u062f\u06cc\u062f \u0634\u062f\u06cc\u062f \u0645\u0633\u06cc\u0631 \u0646\u06cc\u062a\u0631\u06cc\u06a9\u200c\u0627\u06a9\u0633\u0627\u06cc\u062f (cGMP) \u062f\u0631 \u062f\u06cc\u0648\u0627\u0631\u0647 \u0631\u06af\u200c\u0647\u0627 \u0648 \u0627\u0632 \u062f\u0633\u062a \u0631\u0641\u062a\u0646 \u06a9\u0627\u0645\u0644 \u0645\u0642\u0627\u0648\u0645\u062a \u0639\u0631\u0648\u0642\u06cc.","\u0645\u0637\u0644\u0642\u0627\u064b \u0645\u0645\u0646\u0648\u0639 (\u062d\u062f\u0627\u0642\u0644 \u06f2\u06f4 \u062a\u0627 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0641\u0627\u0635\u0644\u0647)",A.c(["\u0633\u0631\u06af\u06cc\u062c\u0647 \u0634\u062f\u06cc\u062f \u0648 \u0633\u06cc\u0627\u0647\u06cc \u0631\u0641\u062a\u0646 \u0686\u0634\u0645","\u063a\u0634 \u06a9\u0631\u062f\u0646 (\u0633\u0646\u06a9\u0648\u067e)","\u062f\u0631\u062f \u0642\u0641\u0633\u0647 \u0633\u06cc\u0646\u0647"],s),"\u0627\u06af\u0631 \u062f\u0627\u0631\u0648\u06cc \u0646\u06cc\u062a\u0631\u0627\u062a \u0642\u0644\u0628\u06cc \u0645\u0635\u0631\u0641 \u0645\u06cc\u200c\u06a9\u0646\u06cc\u062f\u060c \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u0627\u06cc\u0646 \u062f\u0633\u062a\u0647 \u062f\u0627\u0631\u0648\u0647\u0627 \u0645\u0637\u0644\u0642\u0627\u064b \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.")
if(b0.f_(b1,b2,j,i))return new A.cY(B.bt,"\u062a\u062f\u0627\u062e\u0644 \u0634\u062f\u06cc\u062f (\u062e\u0637\u0631 \u0628\u0627\u0644\u0627 \u0631\u0641\u062a\u0646 \u067e\u062a\u0627\u0633\u06cc\u0645 \u062e\u0648\u0646 \u0648 \u0622\u0631\u06cc\u062a\u0645\u06cc \u0642\u0644\u0628)","\u0647\u0631 \u062f\u0648 \u062f\u0627\u0631\u0648\u06cc \xab"+b1.b+"\xbb \u0648 \xab"+b2.b+"\xbb \u0645\u0627\u0646\u0639 \u062f\u0641\u0639 \u067e\u062a\u0627\u0633\u06cc\u0645 \u0627\u0632 \u06a9\u0644\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f. \u0645\u0635\u0631\u0641 \u0647\u0645\u0632\u0645\u0627\u0646 \u0622\u0646\u200c\u0647\u0627 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u067e\u062a\u0627\u0633\u06cc\u0645 \u062e\u0648\u0646 \u0631\u0627 \u0628\u0647 \u0633\u0637\u062d \u062e\u0637\u0631\u0646\u0627\u06a9\u06cc \u0628\u0631\u0633\u0627\u0646\u062f \u06a9\u0647 \u0628\u0631\u0627\u06cc \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a.","\u06a9\u0627\u0647\u0634 \u062a\u0631\u0634\u062d \u0622\u0644\u062f\u0648\u0633\u062a\u0631\u0648\u0646 \u0648 \u06a9\u0627\u0647\u0634 \u062f\u0641\u0639 \u06a9\u0644\u06cc\u0648\u06cc \u067e\u062a\u0627\u0633\u06cc\u0645 \u0628\u0647 \u0637\u0648\u0631 \u0647\u0645\u0632\u0645\u0627\u0646.","\u0641\u0642\u0637 \u0628\u0627 \u062a\u062c\u0648\u06cc\u0632 \u0645\u062a\u062e\u0635\u0635 \u0648 \u0622\u0632\u0645\u0627\u06cc\u0634 \u062e\u0648\u0646 \u0645\u0646\u0638\u0645",A.c(["\u0636\u0639\u0641 \u0648 \u0633\u0646\u06af\u06cc\u0646\u06cc \u0634\u062f\u06cc\u062f \u0639\u0636\u0644\u0627\u062a \u067e\u0627","\u062a\u067e\u0634 \u0642\u0644\u0628 \u0646\u0627\u0645\u0646\u0638\u0645","\u06af\u0632\u06af\u0632 \u062f\u0648\u0631 \u0644\u0628 \u0648 \u0627\u0646\u06af\u0634\u062a\u0627\u0646"],s),"\u062f\u0631 \u0635\u0648\u0631\u062a \u062a\u062c\u0648\u06cc\u0632 \u0647\u0645\u0632\u0645\u0627\u0646 \u062a\u0648\u0633\u0637 \u067e\u0632\u0634\u06a9\u060c \u0627\u0632 \u0645\u0635\u0631\u0641 \u0646\u0645\u06a9\u200c\u0647\u0627\u06cc \u0631\u0698\u06cc\u0645\u06cc \u067e\u062a\u0627\u0633\u06cc\u0645\u200c\u062f\u0627\u0631 \u0648 \u0645\u06a9\u0645\u0644 \u067e\u062a\u0627\u0633\u06cc\u0645 \u062e\u0648\u062f\u062f\u0627\u0631\u06cc \u06a9\u0646\u06cc\u062f.")
